				var editorId = tself.EditorId;
				if(!string.IsNullOrEmpty(editorId))
					bld.Append(editorId);

				var name = tself.Name;
				if(!string.IsNullOrEmpty(name))
				{
					if(bld.Length != 0)
						bld.Append(" ");
					bld.Append("`");
					bld.Append(name);
