						}
						if(sfls.Count > 1)
							sfls.Reverse();
						if(sfls.Count != 0)
						{
							bld.Append(", File: `");
							bld.Append(string.Join(" <- ", sfls));
							bld.Append("`");
						}
					}
				}

				str = bld.ToString();
				if(str != null && str.Length != 0)
				{
					int _wroteInc = ++_wroteCount;
					_bld.Append(_wroteInc == 1 ? "(" : ", ");
					_bld.Append(str);
				}
			}
			if(_wroteCount != 0)
			_bld.Append(")");
			return _bld.ToString();
