			p >>= index;
			p &= mask;
			return p;
		}

		public void SetActorStateData(System.Int32 index, System.Int32 size, System.UInt64 value)
		{
			if(index < 0 || index >= 64)
				throw new ArgumentOutOfRangeException("index");
			if(size <= 0 || size >= 64)
				throw new ArgumentOutOfRangeException("size");

			ulong mask = (ulong)1 << size;
			mask--;

			if((value & mask) != value)
				throw new ArgumentOutOfRangeException("value");

			value <<= index;
			mask <<= index;

			ulong p = NetScriptFramework.Memory.ReadUInt64(this.Address + 0xC0);
			p &= ~mask;
			p |= value;
			NetScriptFramework.Memory.WriteUInt64(this.Address + 0xC0, p);
		}

