		public System.Boolean TranslateTo(System.Single x, System.Single y, System.Single z, System.Single angleX, System.Single angleY, System.Single angleZ, System.Single moveSpeed, System.Single rotateSpeed)
		{
			TESObjectREFR tobj = this;
			var cell = tobj.ParentCell;
			if(cell == null)
				return false;
			var node = tobj.Node;
			if(node == null)
				return false;

			using(var objRef = new ObjectRefHolder(this))
			{
				if(!objRef.IsValid)
					return false;
				objRef.Pin();

				var extra = this.GetExtraData(ExtraDataTypes.RefrPath);
				if(extra == null)
				{
					var extraPtr = NetScriptFramework.Memory.InvokeCdecl(__VIDS.VID66859.Value, __VIDS.VID514110.Value, 104, 0);
					extra = NetScriptFramework.MemoryObject.FromAddress<BSExtraData>(extraPtr);
					extra.Next = null;
					NetScriptFramework.Memory.WritePointer(extraPtr, __VIDS.VID229633.Value);
					NetScriptFramework.Memory.InvokeCdecl(__VIDS.VID12176.Value, this.Address + 0x70, extraPtr);
					this.InvokeVTableThisCall<TESObjectREFR>(0x50, 0x80000000);
				}
				angleX *= 0.017453292f;
				angleY *= 0.017453292f;
				angleZ *= 0.017453292f;
				rotateSpeed *= 0.017453292f;
				using(var alloc = NetScriptFramework.Memory.Allocate(0x40))
				{
					alloc.Zero();
					NetScriptFramework.Memory.WriteFloat(alloc.Address, x);
					NetScriptFramework.Memory.WriteFloat(alloc.Address + 4, y);
					NetScriptFramework.Memory.WriteFloat(alloc.Address + 8, z);
					NetScriptFramework.Memory.WriteFloat(alloc.Address + 0x10, angleX);
					NetScriptFramework.Memory.WriteFloat(alloc.Address + 0x14, angleY);
					NetScriptFramework.Memory.WriteFloat(alloc.Address + 0x18, angleZ);
					NetScriptFramework.Memory.InvokeCdecl(__VIDS.VID12666.Value, extra.Cast<BSExtraData>(), tobj.Position.Address, tobj.Rotation.Address, alloc.Address, alloc.Address + 0x10, moveSpeed, rotateSpeed);
					NetScriptFramework.Memory.WriteUInt32(alloc.Address + 0x20, objRef.Handle);
					bool res = NetScriptFramework.Memory.InvokeCdecl(__VIDS.VID19006.Value, cell.Cast<TESObjectCELL>(), alloc.Address + 0x20).ToBool();
					if(!res)
						objRef.Unpin();
					return res;
				}
			}
		}

		public System.Boolean CastSpell(MagicItem spell, TESObjectREFR target, Actor blame)
		{
			var selfptr = this.Cast<TESObjectREFR>();
			if(selfptr == System.IntPtr.Zero) throw new System.NullReferenceException("this");
			if(spell == null) throw new System.ArgumentNullException("spell");
			var spellPtr = spell.Cast<SpellItem>();
			if(spellPtr == System.IntPtr.Zero) throw new System.InvalidCastException("spell to SpellItem");
			if(target == null) throw new System.ArgumentNullException("target");
			var targetPtr = target.Cast<TESObjectREFR>();
			if(targetPtr == System.IntPtr.Zero) throw new System.InvalidCastException("target to TESObjectREFR");
			var blamePtr = blame != null ? blame.Cast<Actor>() : System.IntPtr.Zero;

			uint stype = spell.InvokeVTableThisCall<MagicItem>(0x298).ToUInt32();
			if(stype <= 0xA && (0x412 & (1 << (int)stype)) != 0)
				return false; // Spell is permanent (e.g. an ability/addiction/disease) and cannot be Cast.

			var caster = this.GetMagicCaster(EquippedSpellSlots.Instant);
			if(caster == null) return false;

			var tes = TES.Instance;
			if(tes == null) return false;
			var tesPtr = tes.Cast<TES>();
			if(tesPtr == IntPtr.Zero) return false;

			var cell = ((TESObjectREFR)this).ParentCell;
			IntPtr cellPtr;
			if(cell == null || (cellPtr = cell.Cast<TESObjectCELL>()) == IntPtr.Zero || !NetScriptFramework.Memory.InvokeCdecl(__VIDS.VID13163.Value, tesPtr, cellPtr, 1).ToBool() || !NetScriptFramework.Memory.InvokeCdecl(__VIDS.VID13163.Value, tesPtr, cellPtr, 0).ToBool())
				return false; // Ref is in an unloaded cell, so it cannot cast spells.

			caster.InterruptCast();
			caster.InvokeVTableThisCall<MagicCaster>(0x8, spellPtr, 0, targetPtr, 1.0f, 0, 0.0f, blamePtr);
			return true;
		}

		public ExtraLock GetLockData(System.Boolean allowTeleportTargetLockData)
		{
			var selfptr = this.Cast<TESObjectREFR>();
			if(selfptr == System.IntPtr.Zero) throw new System.NullReferenceException("this");
			var r = NetScriptFramework.MemoryObject.FromAddress<ExtraLock>(NetScriptFramework.Memory.InvokeCdecl(__VIDS.VID19823.Value, selfptr));
			if(r != null || !allowTeleportTargetLockData)
				return r;

			return NetScriptFramework.MemoryObject.FromAddress<ExtraLock>(NetScriptFramework.Memory.InvokeCdecl(__VIDS.VID19818.Value, selfptr));
		}

		public void PlayEffect(TESEffectShader effect, System.Single duration)
		{
			var selfptr = this.Cast<TESObjectREFR>();
			if(selfptr == System.IntPtr.Zero) throw new System.NullReferenceException("this");
			if(effect == null) throw new System.ArgumentNullException("effect");
			var argptr = effect.Cast<TESEffectShader>();
			if(argptr == System.IntPtr.Zero) throw new System.InvalidCastException("effect to TESEffectShader");
			var self = ((TESObjectREFR)this);
			var cell = self.ParentCell;
			if(cell == null)
				return;

			var tes = TES.Instance;
			if(!NetScriptFramework.Memory.InvokeCdecl(__VIDS.VID13163.Value, tes.Cast<TES>(), cell.Cast<TESObjectCELL>(), 0).ToBool())
				return;

			var node = self.Node;
			if(node == null)
				return;

			NetScriptFramework.Memory.InvokeCdecl(__VIDS.VID19446.Value, selfptr, argptr, duration, 0, 0, 0, 0, 0);
		}

		public void StopEffect(TESEffectShader effect)
		{
			var selfptr = this.Cast<TESObjectREFR>();
