		public System.Boolean CastSpell(MagicItem spell, TESObjectREFR target, Actor blame)
		{
			var selfptr = this.Cast<TESObjectREFR>();
			if(selfptr == System.IntPtr.Zero) throw new System.NullReferenceException("this");
			if(spell == null) throw new System.ArgumentNullException("spell");
			var spellPtr = spell.Cast<SpellItem>();
			if(spellPtr == System.IntPtr.Zero) throw new System.InvalidCastException("spell to SpellItem");
			if(target == null) throw new System.ArgumentNullException("target");
			var targetPtr = target.Cast<TESObjectREFR>();
			if(targetPtr == System.IntPtr.Zero) throw new System.InvalidCastException("target to TESObjectREFR");
			var blamePtr = blame != null ? blame.Cast<Actor>() : System.IntPtr.Zero;

			uint stype = spell.InvokeVTableThisCall<MagicItem>(0x298).ToUInt32();
			if(stype <= 0xA && (0x412 & (1 << (int)stype)) != 0)
				return false; // Spell is permanent (e.g. an ability/addiction/disease) and cannot be Cast.

			var caster = this.GetMagicCaster(EquippedSpellSlots.Instant);
			if(caster == null) return false;

			var tes = TES.Instance;
			if(tes == null) return false;
			var tesPtr = tes.Cast<TES>();
			if(tesPtr == IntPtr.Zero) return false;

			var cell = ((TESObjectREFR)this).ParentCell;
			IntPtr cellPtr;
			if(cell == null || (cellPtr = cell.Cast<TESObjectCELL>()) == IntPtr.Zero || !NetScriptFramework.Memory.InvokeCdecl(__VIDS.VID13163.Value, tesPtr, cellPtr, 1).ToBool() || !NetScriptFramework.Memory.InvokeCdecl(__VIDS.VID13163.Value, tesPtr, cellPtr, 0).ToBool())
				return false; // Ref is in an unloaded cell, so it cannot cast spells.

			caster.InterruptCast();
			caster.InvokeVTableThisCall<MagicCaster>(0x8, spellPtr, 0, targetPtr, 1.0f, 0, 0.0f, blamePtr);
			return true;
		}

