		public override System.Collections.Generic.IReadOnlyList<NetScriptFramework.GameInfo.GameTypeInstanceInfo> TypeInfos { get { return NetScriptFramework.Main.GameInfo.GetTypeInstanceInfos(8349); } }

		public override System.String ToString()
		{
			var _bld = new System.Text.StringBuilder(128);
			int _wroteCount = 0;
			_bld.Append(base.ToString());
			{
				System.String str = null;
				var bld = new System.Text.StringBuilder(128);

				TESForm tself = this;
				var editorId = tself.EditorId;
				if(!string.IsNullOrEmpty(editorId))
					bld.Append(editorId);

				var name = tself.Name;
				if(!string.IsNullOrEmpty(name))
				{
					if(bld.Length != 0)
						bld.Append(" ");
					bld.Append("`");
					bld.Append(name);
					bld.Append("`");
				}

				if(bld.Length != 0)
				{
					bld.Insert(0, "Name: ");
					bld.Append(", ");
				}
				bld.Append("FormId: ");
				bld.Append(tself.FormId.ToString("X8"));
				//bld.Append(", FormType: ");
				//bld.Append(tself.FormType.ToString());

				var fa = tself.FormSourceFiles;
				if(fa != null)
				{
					var sls = fa.FileArray;
					if(sls != null)
					{
						var sfls = new System.Collections.Generic.List<string>(4);
						foreach(var x in sls)
						{
							string sfn = x.Name;
							if(!string.IsNullOrEmpty(sfn))
								sfls.Add(sfn);
						}
						if(sfls.Count > 1)
							sfls.Reverse();
						if(sfls.Count != 0)
						{
							bld.Append(", File: `");
							bld.Append(string.Join(" <- ", sfls));
							bld.Append("`");
						}
					}
				}

				str = bld.ToString();
				if(str != null && str.Length != 0)
				{
					int _wroteInc = ++_wroteCount;
					_bld.Append(_wroteInc == 1 ? "(" : ", ");
					_bld.Append(str);
				}
			}
			{
				System.String str = null;
				var form = ((TESObjectREFR)this).BaseForm;
				str = "BaseForm: " + (form != null ? form.ToString() : "null");
				if(str != null && str.Length != 0)
				{
					int _wroteInc = ++_wroteCount;
					_bld.Append(_wroteInc == 1 ? "(" : ", ");
					_bld.Append(str);
				}
			}
			if(_wroteCount != 0)
			_bld.Append(")");
			return _bld.ToString();
		}

