		public System.Collections.Generic.List<TESObjectCELL> GetLoadedCells()
		{
			TES tself = this;
			System.Collections.Generic.List<TESObjectCELL> ls;
			var interior = tself.CurrentInteriorCell;
			if(interior != null)
			{
				ls = new System.Collections.Generic.List<TESObjectCELL>(1);
				if(interior.IsAttached)
					ls.Add(interior);
			}
			else
			{
				ls = new System.Collections.Generic.List<TESObjectCELL>(32);
				var grid = tself.CellGrid;
				if(grid != null)
				{
					int length = grid.Length;
					for(int i = 0; i < length; i++)
					{
						for(int j = 0; j < length; j++)
						{
							var cell = grid.GetCell(i, j);
							if(cell != null && cell.IsAttached)
								ls.Add(cell);
						}
					}
				}
			}
			return ls;
		}

