		public void Translate(NiPoint3 amount, NiPoint3 result)
		{
			if(amount == null)
				throw new System.ArgumentNullException("amount");
			if(result == null)
				throw new System.ArgumentNullException("result");
			NiTransform tself = this;

			var a = new float[] { amount.X, amount.Y, amount.Z };
			var m = tself.Rotation.Data.ToArray();
			var r = new float[3];

			r[0] = m[0] * a[0] + m[1] * a[1] + m[2] * a[2] + tself.Position.X;
			r[1] = m[3] * a[0] + m[4] * a[1] + m[5] * a[2] + tself.Position.Y;
			r[2] = m[6] * a[0] + m[7] * a[1] + m[8] * a[2] + tself.Position.Z;

			result.X = r[0];
			result.Y = r[1];
			result.Z = r[2];
		}

		public void LookAt(NiPoint3 target)
		{
			if(target == null)
				throw new System.ArgumentNullException("target");

			NiTransform tself = this;
			using(var alloc = NetScriptFramework.Memory.Allocate(0x40))
			{
				//alloc.Zero();

