				var y = NetScriptFramework.MemoryObject.FromAddress<NiPoint3>(alloc.Address + 0x10);
				var up = NetScriptFramework.MemoryObject.FromAddress<NiPoint3>(alloc.Address + 0x20);
				var dir = NetScriptFramework.MemoryObject.FromAddress<NiPoint3>(alloc.Address + 0x30);

				var pos = tself.Position;
				dir.X = target.X - pos.X;
				dir.Y = target.Y - pos.Y;
				dir.Z = target.Z - pos.Z;
				dir.Normalize(dir);

				var z = dir;

				up.X = 0.0f;
				up.Y = 0.0f;
				up.Z = 1.0f;

				up.Cross(z, x);
				x.Normalize(x);

				z.Cross(x, y);
				y.Normalize(y);

				var rot = tself.Rotation;
				rot[0, 0] = -x.X;
				rot[1, 0] = -x.Y;
				rot[2, 0] = -x.Z;
				rot[0, 1] = z.X;
				rot[1, 1] = z.Y;
				rot[2, 1] = z.Z;
				rot[0, 2] = y.X;
				rot[1, 2] = y.Y;
				rot[2, 2] = y.Z;
			}
