		public void Inverse(NiMatrix33 result)
		{
			if(result == null)
				throw new System.ArgumentNullException("result");

			NiMatrix33 tself = this;
			float[] tmp = new float[9];
			float[] m = tself.Data.ToArray();

			tmp[0] = m[4] * m[8] - m[5] * m[7];
			tmp[1] = m[2] * m[7] - m[1] * m[8];
			tmp[2] = m[1] * m[5] - m[2] * m[4];
			tmp[3] = m[5] * m[6] - m[3] * m[8];
			tmp[4] = m[0] * m[8] - m[2] * m[6];
			tmp[5] = m[2] * m[3] - m[0] * m[5];
			tmp[6] = m[3] * m[7] - m[4] * m[6];
			tmp[7] = m[1] * m[6] - m[0] * m[7];
			tmp[8] = m[0] * m[4] - m[1] * m[3];

			float determinant = m[0] * tmp[0] + m[1] * tmp[3] + m[2] * tmp[6];
			if ((float)System.Math.Abs(determinant) <= System.Single.Epsilon)
